import importlib.util,json,unittest
from pathlib import Path
W=Path('/private/tmp/lora-mismatch-trim-cycle');R=Path('/Users/goshua/next-order')
def load(p,name):
 spec=importlib.util.spec_from_file_location(name,p);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m.trim_to_sentence
old=load(W/'json_extract.before.py','old');new=load(R/'ml/common/json_extract.py','candidate')
class TrimTests(unittest.TestCase):
 def test_short_unchanged(self):
  t='정답은 ②. "don\'t"라는 표현과 다릅니다.';self.assertEqual(new(t),t)
 def test_unquoted_unchanged(self):
  t='완성된 해설입니다. '*60;self.assertEqual(new(t),old(t))
 def test_quote_styles(self):
  for a,b in [('"','"'),("'","'"),('“','”'),('‘','’')]:
   with self.subTest(a=a):
    prefix='확인한 근거와 일치합니다. '*15;t=prefix+a+'Using a telescope... '+('word '*60)+b+'라는 근거입니다.'
    self.assertEqual(new(t),prefix.rstrip());self.assertNotEqual(old(t),new(t))
 def test_contraction(self):
  prefix='확인한 근거와 일치합니다. '*15;t=prefix+"'we don't eat... "+('word '*60)+"'라는 근거입니다."
  self.assertEqual(new(t),prefix.rstrip())
 def test_possessive(self):
  t="dogs' 피부를 설명합니다. "*60;self.assertEqual(new(t),old(t))
 def test_closed_quote_then_sentence(self):
  prefix=('근거가 맞습니다. '*25)+'"Sentence. "와 일치합니다. ';t=prefix+('추가 설명 '*80)
  self.assertEqual(new(t),prefix.rstrip())
 def test_sparse_boundary_fallback_unchanged(self):
  t='짧은 문장입니다. '+('문장 부호 없는 해설 '*80);self.assertEqual(new(t),old(t))
 def test_synthetic_continuation_of_observed_failures(self):
  for st,num,rep in [('sep26-go1','24번',2),('jun11-go2','26번',2)]:
   rows=[json.loads(x) for x in (R/f'ml/eval/runs/{st}/2026-09-27-mismatch-trim-before.jsonl').read_text().splitlines()]
   r=next(x for x in rows if x['num']==num and x['rep']==rep);t=r['explanation']+(' continuation '*30)+'"라는 근거와 일치합니다.'
   self.assertEqual(old(t).count('"')%2,1);self.assertEqual(new(t).count('"')%2,0)
if __name__=='__main__':unittest.main(verbosity=2)
